import React from 'react';

const Navbar = ({ onNavigate }) => {
  return (
    <nav className="bg-blue-600 text-white p-4">
      <div className="container mx-auto flex justify-between items-center">
        <button 
          onClick={() => onNavigate('propertyList')} 
          className="text-2xl font-bold bg-transparent border-0 text-white cursor-pointer"
        >
          ApartmentFinder
        </button>
        <div className="space-x-4">
          <button 
            onClick={() => onNavigate('propertyList')} 
            className="bg-transparent border-0 text-white hover:underline cursor-pointer"
          >
            Properties
          </button>
          <button 
            onClick={() => onNavigate('propertyForm')} 
            className="bg-white text-blue-600 px-4 py-2 rounded hover:bg-blue-100 border-0 cursor-pointer"
          >
            Add Property
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
